\begin{lemma}[Local Frame Criterion for Subbundles]
\label{lem:local-frame-criterion-for-subbundles}

\uses{lem:vector-bundle-chart-lemma, def:riemannian-metric, prop:existence-orthonormal-frames}




\dcref{chA:A.34}
Let $\pi: E \to M$ be a smooth vector bundle endowed with a smooth fibre metric $\langle\cdot,\cdot\rangle$, and suppose that for each $p \in M$ we are given a $k$-dimensional linear subspace $D_p \subseteq E_p$. Suppose further that each $p \in M$ has a neighborhood $U$ on which there are smooth local sections $\sigma_1, \ldots, \sigma_k: U \to E$ such that $\sigma_1(q), \ldots, \sigma_k(q)$ form a basis for $D_q$ at each $q \in U$. Then $D = \bigcup_{p \in M} D_p \subseteq E$ is a smooth subbundle of $E$: it carries a smooth rank-$k$ vector bundle structure over $M$ whose fibre at $p$ is $D_p$ with the linear structure inherited from $E_p$.
\end{lemma}

